(* [comment removed for export] *)
Definition tokit_cells_gen (r : tokres) (cur fst last : Z) : list cell :=
  match r with
  | TK_tok k l => TokItCells (cur + Z.of_nat k) (Z.of_nat l) (cur + Z.of_nat k + Z.of_nat l) fst last
  | _ => TokItCells 0 0 last last last
  end.

Lemma tokit_cells_gen_after : forall r it0 last, tokit_cells_after r it0 last = tokit_cells_gen r it0 it0 last.
Proof. intros [| |k l] it0 last; reflexivity. Qed.

Lemma tokit_cells_gen_shift : forall r cur fst last,
  tokit_cells_gen (tk_shift r) cur fst last = tokit_cells_gen r (cur + 1) fst last.
Proof.
  intros [| |k l] cur fst last; cbn; try reflexivity. unfold TokItCells.
  replace (cur + Z.of_nat (S k)) with (cur + 1 + Z.of_nat k) by lia. reflexivity.
Qed.

(* [comment removed for export] *)
Definition tk_side (m : mem) (A W n : Z) : Prop := ACONST m /\ aobj m A SZ_TOKIT /\ accessible m W n.

Lemma tk_side_now : forall m m1 A W n lo hi,
  tk_side m A W n -> munch [(lo, hi); (A, A + SZ_TOKIT)]%Z m m1 -> wmono bsegs m m1 -> aceil <= lo ->
  tk_side m1 A W n.
Proof.
  intros m m1 A W n lo hi (AC & AO & AW) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi); (A, A + SZ_TOKIT)]%Z)
    by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_cons; [exact (aobj_awin _ _ _ AO)| apply Forall_nil]]).
  split; [eapply aconst_transport_awin; fast_eassumption|].
  split; [eapply aobj_transport; fast_eassumption| eapply acc_transport_awin; fast_eassumption].
Qed.

(* [comment removed for export] *)
Definition tokit_post_c (cells : list cell) (a0k : option Z)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A W lo : Z) (wbs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ (forall z, a0k = Some z -> a0 = wz z)
    /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' A cells
    /\ bytes_at bsegs m' W wbs
    /\ ACONST m' /\ aobj m' A SZ_TOKIT /\ accessible m' W (Z.of_nat (length wbs)).

Definition tokit_pure (sp : word) (A W lo : Z) (wbs : list byte) (fst La : Z) : Prop :=
  La = W + Z.of_nat (length wbs) /\ La < 2^64 /\ 0 <= fst < 2^64
  /\ (A + SZ_TOKIT <= W \/ W + Z.of_nat (length wbs) <= A)
  /\ lo + TOKIT_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= A \/ A + SZ_TOKIT <= lo)
  /\ (bv_unsigned sp <= W \/ W + Z.of_nat (length wbs) <= lo)
  /\ A mod 8 = 0
  /\ ((0 < length wbs)%nat -> 0 < W).                                 (* [comment removed for export] *)

(* [comment removed for export] *)
Definition zeros16 : list byte := poison_bytes 16 0.

(* [comment removed for export] *)
Lemma tokit_join : forall m A (c0 c1 : cell) x y z,
  rw_cells bsegs m A [c0; c1] -> csize c0 = 8%nat -> csize c1 = 8%nat ->
  rw_cells bsegs m (A + 16) [C8 x; C8 y; C8 z] ->
  rw_cells bsegs m A [c0; c1; C8 x; C8 y; C8 z].
Proof.
  intros m A c0 c1 x y z V S0 S1 O.
  apply (proj2 (rw_cells_app bsegs m A [c0; c1] [C8 x; C8 y; C8 z])). split; [exact V|].
  cbn [cells_size]. rewrite S0, S1. exact O.
Qed.
Lemma tokit_join0 : forall m A x y z,
  rw_cells bsegs m A [CB 16 zeros16] -> rw_cells bsegs m (A + 16) [C8 x; C8 y; C8 z] ->
  rw_cells bsegs m A [C8 (wz 0); C8 (wz 0); C8 x; C8 y; C8 z].
Proof.
  intros m A x y z V O.
  assert (V' : rw_cells bsegs m A [C8 (wz 0); C8 (wz 0)])
    by (eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity| vm_compute; reflexivity]).
  apply tokit_join; [exact V'| reflexivity| reflexivity| exact O].
Qed.

(* [comment removed for export] *)
Lemma awin_sub : forall l h l' h', awin (l, h) -> l <= l' -> h' <= h -> awin (l', h').
Proof.
  intros l h l' h' (K1 & K2 & K3) L1 L2. split; [| split].
  - intros a Ha. apply K1. cbn in Ha |- *. lia.
  - unfold stack0_ok in *. cbn in K2 |- *. lia.
  - cbn in K3 |- *. lia.
Qed.

(* [comment removed for export] *)
Lemma wspan_stop : forall s, (wspan s < length s)%nat -> is_ws (nth (wspan s) s 0) = false.
Proof.
  induction s as [|c s IH]; intros H; cbn in H |- *; [lia|].
  destruct (is_ws c) eqn:W; [| exact W]. cbn. apply IH. lia.
Qed.
Fixpoint tk_shiftn (n : nat) (r : tokres) : tokres := match n with 0%nat => r | S n' => tk_shift (tk_shiftn n' r) end.
Lemma tok_next_wspan : forall nc s, tok_next nc s = tk_shiftn (wspan s) (tok_next nc (skipn (wspan s) s)).
Proof.
  intros nc s. revert nc. induction s as [|c s IH]; intros nc; [reflexivity|].
  cbn [wspan]. destruct (is_ws c) eqn:W.
  - cbn [tk_shiftn skipn]. rewrite <- IH. cbn [tok_next]. rewrite W. reflexivity.
  - cbn [tk_shiftn skipn]. reflexivity.
Qed.
Lemma tokit_cells_gen_shiftn : forall n r cur fst last,
  tokit_cells_gen (tk_shiftn n r) cur fst last = tokit_cells_gen r (cur + Z.of_nat n) fst last.
Proof.
  induction n as [|n IH]; intros r cur fst last; cbn [tk_shiftn].
  - rewrite Z.add_0_r. reflexivity.
  - rewrite tokit_cells_gen_shift, IH. f_equal. lia.
Qed.
Lemma skipn_skipn' : forall {X} (a b : nat) (l : list X), skipn a (skipn b l) = skipn (b + a) l.
Proof. intros X a b l. rewrite skipn_skipn. f_equal. lia. Qed.
Lemma tokit_cells_gen_wspan : forall nc i (s : list Z) cur fst last,
  tokit_cells_gen (tok_next nc (skipn i s)) cur fst last
  = tokit_cells_gen (tok_next nc (skipn (i + wspan (skipn i s)) s)) (cur + Z.of_nat (wspan (skipn i s))) fst last.
Proof.
  ltac2:(KReplay.run [|constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.nat); constr:(@Corelib.Init.Datatypes.list); constr:(@Corelib.Numbers.BinNums.Z); constr:(@Corelib.Init.Logic.eq); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok_stmt.tokres); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok_stmt.tok_next); constr:(@Corelib.Lists.ListDef.skipn); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok.TK.tk_shiftn); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_skipows.wspan); constr:(@Corelib.Classes.Morphisms.trans_co_eq_inv_impl_morphism); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Cells.cell); constr:(@Corelib.Classes.RelationClasses.eq_Transitive); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok.TK.tokit_cells_gen); constr:(@Corelib.Classes.Morphisms.reflexive_proper); constr:(@Corelib.Classes.Morphisms.respectful); constr:(@Corelib.Classes.Morphisms.reflexive_reflexive_proxy); constr:(@Corelib.Classes.Morphisms.reflexive_eq_dom_reflexive); constr:(@Corelib.Classes.RelationClasses.eq_Reflexive); constr:(@Corelib.Classes.Morphisms.eq_proper_proxy); constr:(@Corelib.Init.Nat.add); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Stdlib.ZArith.BinInt.Z.of_nat); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok.TK.tok_next_wspan); constr:(@Corelib.Init.Logic.eq_ind_r); constr:(@Corelib.Init.Logic.eq_refl); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok.TK.skipn_skipn'); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_tok.TK.tokit_cells_gen_shiftn)|] [|@last; @fst; @cur; @r; @lemma; @l; @s; @i; @nc|] "##n#*#F#0#$#%#&###(#'#2#)#/#6#5#:#A#C#B#E#1#8#9#?#=#;#7#D#F#G#H#.#-#3#4#<#>#@+#A%#/'#B&#C'#D'#E%#4&#4$ULC%CIF#H#UM$%C#%#H#VN%#)J'#ULS%*#US&$%CHI#K#$#FEDUM%%C#&#K#VN%#$#FEDk#$C-k#%C#k#&C#k#'J#*J*C&C3#2&C)$#&C)%#&J)'#US'7'C87#'C.(#'C.(#'J.(#WS(.(#(CF(CE(CDdS)2,&O<7GFF%EE$DD#VPH;%C#I#K#UQ>VRF#$%#ED(s#'#]S*s#(s#'s#&s##>*$$#j#(s#*#VS+Hs#1UQs#0VRE#$s#0#DG)s#.G*j#)s#/#VPIs#5%C#F#KG$#0ED)s#4#0j#)s#=##H'$#-DGVS,s#8#XS-Cs#>IFZS#s#B+'$s#>#$s#=EDGYS.s#As#?EDGZS#s#=20%$#V76#j#$C#j#%C#j#&C#j#*s#J#j#+S/#j#,S0##"). Qed.
Lemma wspan_skip_stop : forall i (s : list Z), (i + wspan (skipn i s) < length s)%nat ->
  is_ws (nth (i + wspan (skipn i s)) s 0) = false.
Proof.
  intros i s H.
  pose proof (wspan_stop (skipn i s)) as W. rewrite length_skipn in W. rewrite nth_skipn in W. apply W. lia.
Qed.
Lemma zbytes_nth : forall (wbs : list byte) j b, nth_error wbs j = Some b -> nth j (zbytes wbs) 0 = zb b.
Proof. intros wbs j b N. apply nth_error_nth. unfold zbytes. rewrite nth_error_map, N. reflexivity. Qed.
Lemma wspan_skip_le : forall i (s : list Z), (i <= length s)%nat -> (i + wspan (skipn i s) <= length s)%nat.
Proof. intros i s Hi. pose proof (wspan_le (skipn i s)) as W. rewrite length_skipn in W. lia. Qed.
