Ltac tk_ochk SD MU WM CEIL A k AL PRE :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AO := fresh "AO" in let RD := fresh "RD" in
    destruct (tk_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (_ & AO & _);
    pose proof (accessible_read0_sr mc A 40 (A + k) (aobj_acc _ _ _ AO) ltac:(lia)
                  ltac:(clear - AL; unhideL; Z.div_mod_to_equations; lia) ltac:(lia)) as RD;
    rewrite ?Z.add_0_r in RD; clear AO;
    PRE; clear RD;
    try replace (zxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity);
    try replace (sxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity);
    shchk_br
  end.

(* [comment removed for export] *)
Ltac tk_bchk SD MU WM CEIL a PRE :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AP := fresh "AP" in let v := fresh "v" in let V1 := fresh "V1" in let V2 := fresh "V2" in let RD := fresh "RD" in
    let w := fresh "w" in
    destruct (tk_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (_ & _ & AP);
    destruct (accessible_readw_sr mc a 1 (accessible_sub _ _ _ a 1 AP ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)
                ltac:(clear; Z.div_mod_to_equations; lia)) as (v & V1 & V2 & RD);
    clear AP;
    PRE; clear RD;
    first [ rewrite (sxb_b8_small v) by (clear - V1; lia) | rewrite (zxb_b8_small v) by (clear - V1; lia) ];
    shchk_join_ge V1 V2; intros w; clear V1 V2
  end.

(* [comment removed for export] *)
Ltac tk_tchk SD MU WM CEIL TH x PRE :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AC := fresh "AC" in let RD := fresh "RD" in
    destruct (tk_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (AC & _);
    pose proof (accessible_read0_in mc AL_TAB_IS_TOKEN_CHAR 256 x (TH mc AC) ltac:(reflexivity) ltac:(reflexivity)
                  ltac:(unfold AL_TAB_IS_TOKEN_CHAR; lia)) as RD; clear AC;
    PRE; clear RD;
    try replace (sxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity);
    shchk_br
  end.

