Definition tk_saved (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition bctor_ctx (m m1 : mem) (sp : word) (SV : list cell) (A W lo : Z) (wbs : list byte) (cur fst La : Z) (j8 : list byte) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -112) (CB 8 j8 :: SV)
  /\ rw_cells bsegs m1 A [CB 16 zeros16]
  /\ rw_cells bsegs m1 (A + 16) [C8 (wz cur); C8 (wz fst); C8 (wz La)]
  /\ bytes_at bsegs m1 W wbs
  /\ stk bsegs m1 lo (bv_unsigned sp + -112)
  /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ tk_side m A W (Z.of_nat (length wbs)).

Local Ltac open_bctx CTX PURE :=
  destruct CTX as (FR & V & OBJ & WIN & ST & MU & WM & MI & SD);
